    46	static int set_default_flags(int *flags)
    47	{
    48	  if (((*flags) & IDN2_TRANSITIONAL) && ((*flags) & IDN2_NONTRANSITIONAL))
    49	    return IDN2_INVALID_FLAGS;
    50	
    51	  if (((*flags) & (IDN2_TRANSITIONAL|IDN2_NONTRANSITIONAL)) && ((*flags) & IDN2_NO_TR46))
    52	    return IDN2_INVALID_FLAGS;
    53	
    54	  if (!((*flags) & (IDN2_NO_TR46|IDN2_TRANSITIONAL)))
    55	    *flags |= IDN2_NONTRANSITIONAL;
    56	
    57	  return IDN2_OK;
    58	}
