   139	static int
   140	_tr46 (const uint8_t * domain_u8, uint8_t ** out, int flags)
   141	{
   142	  size_t len, it;
   143	  uint32_t *domain_u32;
   144	  int err = IDN2_OK, rc;
   145	  int transitional = 0;
   146	  int test_flags;
   147	
   148	  if (flags & IDN2_TRANSITIONAL)
   149	    transitional = 1;
   150	
   151	  /* convert UTF-8 to UTF-32 */
   152	  if (!(domain_u32 =
   153	       u8_to_u32 (domain_u8, u8_strlen (domain_u8) + 1, NULL, &len)))
   154	    {
   155	      if (errno == ENOMEM)
   156	        return IDN2_MALLOC;
   157	      return IDN2_ENCODING_ERROR;
   158	    }
   159	
   160	  size_t len2 = 0;
   161	  for (it = 0; it < len - 1; it++)
   162	    {
   163	      IDNAMap map;
   164	
   165	      get_idna_map (domain_u32[it], &map);
   166	
   167	      if (map_is (&map, TR46_FLG_DISALLOWED))
   168	        {
   169	          if (domain_u32[it])
   170	            {
   171	              free (domain_u32);
   172	              return IDN2_DISALLOWED;
   173	            }
   174	          len2++;
   175	        }
   176	      else if (map_is (&map, TR46_FLG_MAPPED))
   177	        {
   178	          len2 += map.nmappings;
   179	        }
   180	      else if (map_is (&map, TR46_FLG_VALID))
   181	        {
   182	          len2++;
   183	        }
   184	      else if (map_is (&map, TR46_FLG_IGNORED))
   185	        {
   186	          continue;
   187	        }
   188	      else if (map_is (&map, TR46_FLG_DEVIATION))
   189	        {
   190	          if (transitional)
   191	            {
   192	              len2 += map.nmappings;
   193	            }
   194	          else
   195	            len2++;
   196	        }
   197	      else if (!(flags & IDN2_USE_STD3_ASCII_RULES))
   198	        {
   199	          if (map_is (&map, TR46_FLG_DISALLOWED_STD3_VALID))
   200	            {
   201	              /* valid because UseSTD3ASCIIRules=false, see #TR46 5 */
   202	              len2++;
   203	            }
   204	          else if (map_is (&map, TR46_FLG_DISALLOWED_STD3_MAPPED))
   205	            {
   206	              /* mapped because UseSTD3ASCIIRules=false, see #TR46 5 */
   207	              len2 += map.nmappings;
   208	            }
   209	        }
   210	    }
   211	
   212	  uint32_t *tmp = (uint32_t *) malloc ((len2 + 1) * sizeof (uint32_t));
   213	  if (!tmp)
   214	    {
   215	      free (domain_u32);
   216	      return IDN2_MALLOC;
   217	    }
   218	
   219	  len2 = 0;
   220	  for (it = 0; it < len - 1; it++)
   221	    {
   222	      uint32_t c = domain_u32[it];
   223	      IDNAMap map;
   224	
   225	      get_idna_map (c, &map);
   226	
   227	      if (map_is (&map, TR46_FLG_DISALLOWED))
   228	        {
   229	          tmp[len2++] = c;
   230	        }
   231	      else if (map_is (&map, TR46_FLG_MAPPED))
   232	        {
   233	          len2 += get_map_data (tmp + len2, &map);
   234	        }
   235	      else if (map_is (&map, TR46_FLG_VALID))
   236	        {
   237	          tmp[len2++] = c;
   238	        }
   239	      else if (map_is (&map, TR46_FLG_IGNORED))
   240	        {
   241	          continue;
   242	        }
   243	      else if (map_is (&map, TR46_FLG_DEVIATION))
   244	        {
   245	          if (transitional)
   246	            {
   247	              len2 += get_map_data (tmp + len2, &map);
   248	            }
   249	          else
   250	            tmp[len2++] = c;
   251	        }
   252	      else if (!(flags & IDN2_USE_STD3_ASCII_RULES))
   253	        {
   254	          if (map_is (&map, TR46_FLG_DISALLOWED_STD3_VALID))
   255	            {
   256	              tmp[len2++] = c;
   257	            }
   258	          else if (map_is (&map, TR46_FLG_DISALLOWED_STD3_MAPPED))
   259	            {
   260	              len2 += get_map_data (tmp + len2, &map);
   261	            }
   262	        }
   263	    }
   264	  free (domain_u32);
   265	
   266	  /* Normalize to NFC */
   267	  tmp[len2] = 0;
   268	  domain_u32 = u32_normalize (UNINORM_NFC, tmp, len2 + 1, NULL, &len);
   269	  free (tmp);
   270	  tmp = NULL;
   271	
   272	  if (!domain_u32)
   273	    {
   274	      if (errno == ENOMEM)
   275	        return IDN2_MALLOC;
   276	      return IDN2_ENCODING_ERROR;
   277	    }
   278	
   279	  /* split into labels and check */
   280	  uint32_t *e, *s;
   281	  for (e = s = domain_u32; *e; s = e)
   282	    {
   283	      while (*e && *e != '.')
   284	        e++;
   285	
   286	      if (e - s >= 4 && s[0] == 'x' && s[1] == 'n' && s[2] == '-'
   287	          && s[3] == '-')
   288	        {
   289	          /* decode punycode and check result non-transitional */
   290	          size_t ace_len;
   291	          uint32_t name_u32[IDN2_LABEL_MAX_LENGTH];
   292	          size_t name_len = IDN2_LABEL_MAX_LENGTH;
   293	          uint8_t *ace;
   294	
   295	          ace = u32_to_u8 (s + 4, e - s - 4, NULL, &ace_len);
   296	          if (!ace)
   297	            {
   298	              free (domain_u32);
   299	              if (errno == ENOMEM)
   300	                return IDN2_MALLOC;
   301	              return IDN2_ENCODING_ERROR;
   302	            }
   303	
   304	          rc =
   305	            _idn2_punycode_decode (ace_len, (char *) ace, &name_len, name_u32);
   306	
   307	          free (ace);
   308	
   309	          if (rc)
   310	            {
   311	              free (domain_u32);
   312	              return rc;
   313	            }
   314	
   315	          test_flags = TR46_NONTRANSITIONAL_CHECK;
   316	
   317	          if (!(flags & IDN2_USE_STD3_ASCII_RULES))
   318	            test_flags |= TEST_ALLOW_STD3_DISALLOWED;
   319	
   320	          if ((rc =
   321	               _idn2_label_test (test_flags, name_u32,
   322	                                 name_len)))
   323	            err = rc;
   324	        }
   325	      else
   326	        {
   327	          test_flags = transitional ? TR46_TRANSITIONAL_CHECK : TR46_NONTRANSITIONAL_CHECK;
   328	
   329	          if (!(flags & IDN2_USE_STD3_ASCII_RULES))
   330	            test_flags |= TEST_ALLOW_STD3_DISALLOWED;
   331	
   332	          if ((rc =
   333	               _idn2_label_test (test_flags, s, e - s)))
   334	            err = rc;
   335	        }
   336	
   337	      if (*e)
   338	        e++;
   339	    }
   340	
   341	  if (err == IDN2_OK && out)
   342	    {
   343	      uint8_t *_out = u32_to_u8 (domain_u32, len, NULL, &len);
   344	      free (domain_u32);
   345	
   346	      if (!_out)
   347	        {
   348	          if (errno == ENOMEM)
   349	            return IDN2_MALLOC;
   350	          return IDN2_ENCODING_ERROR;
   351	        }
   352	
   353	      *out = _out;
   354	    }
   355	  else
   356	    free (domain_u32);
   357	
   358	  return err;
   359	}
   360	
   361	/**
   362	 * idn2_lookup_u8:
   363	 * @src: input zero-terminated UTF-8 string in Unicode NFC normalized form.
   364	 * @lookupname: newly allocated output variable with name to lookup in DNS.
   365	 * @flags: optional #idn2_flags to modify behaviour.
   366	 *
   367	 * Perform IDNA2008 lookup string conversion on domain name @src, as
   368	 * described in section 5 of RFC 5891.  Note that the input string
   369	 * must be encoded in UTF-8 and be in Unicode NFC form.
   370	 *
   371	 * Pass %IDN2_NFC_INPUT in @flags to convert input to NFC form before
   372	 * further processing.  %IDN2_TRANSITIONAL and %IDN2_NONTRANSITIONAL
   373	 * do already imply %IDN2_NFC_INPUT.
   374	 * Pass %IDN2_ALABEL_ROUNDTRIP in @flags to
   375	 * convert any input A-labels to U-labels and perform additional
   376	 * testing (not implemented yet).
   377	 * Pass %IDN2_TRANSITIONAL to enable Unicode TR46
   378	 * transitional processing, and %IDN2_NONTRANSITIONAL to enable
   379	 * Unicode TR46 non-transitional processing.  Multiple flags may be
   380	 * specified by binary or:ing them together.
   381	 *
   382	 * After version 2.0.3: %IDN2_USE_STD3_ASCII_RULES disabled by default.
   383	 * Previously we were eliminating non-STD3 characters from domain strings
   384	 * such as _443._tcp.example.com, or IPs 1.2.3.4/24 provided to libidn2
   385	 * functions. That was an unexpected regression for applications switching
   386	 * from libidn and thus it is no longer applied by default.
   387	 * Use %IDN2_USE_STD3_ASCII_RULES to enable that behavior again.
   388	 *
   389	 * After version 0.11: @lookupname may be NULL to test lookup of @src
   390	 * without allocating memory.
   391	 *
   392	 * Returns: On successful conversion %IDN2_OK is returned, if the
   393	 *   output domain or any label would have been too long
   394	 *   %IDN2_TOO_BIG_DOMAIN or %IDN2_TOO_BIG_LABEL is returned, or
   395	 *   another error code is returned.
   396	 *
   397	 * Since: 0.1
   398	 **/
   399	int
   400	idn2_lookup_u8 (const uint8_t * src, uint8_t ** lookupname, int flags)
   401	{
   402	  size_t lookupnamelen = 0;
   403	  uint8_t _lookupname[IDN2_DOMAIN_MAX_LENGTH + 1];
   404	  uint8_t _mapped[IDN2_DOMAIN_MAX_LENGTH + 1];
   405	  int rc;
   406	
   407	  if (src == NULL)
   408	    {
   409	      if (lookupname)
   410	        *lookupname = NULL;
   411	      return IDN2_OK;
   412	    }
   413	
   414	  rc = set_default_flags(&flags);
   415	  if (rc != IDN2_OK)
   416	    return rc;
   417	
   418	  if (!(flags & IDN2_NO_TR46))
   419	    {
   420	      uint8_t *out;
   421	      size_t outlen;
   422	
   423	      rc = _tr46 (src, &out, flags);
   424	      if (rc != IDN2_OK)
   425	        return rc;
   426	
   427	      outlen = u8_strlen (out);
   428	      if (outlen >= sizeof (_mapped))
   429	        {
   430	          free (out);
   431	          return IDN2_TOO_BIG_DOMAIN;
   432	        }
   433	
   434	      memcpy (_mapped, out, outlen + 1);
   435	      src = _mapped;
   436	      free (out);
   437	    }
   438	
   439	  do
   440	    {
   441	      const uint8_t *end = (uint8_t *) strchrnul ((const char *) src, '.');
   442	      /* XXX Do we care about non-U+002E dots such as U+3002, U+FF0E
   443	         and U+FF61 here?  Perhaps when IDN2_NFC_INPUT? */
   444	      size_t labellen = end - src;
   445	      uint8_t tmp[IDN2_LABEL_MAX_LENGTH];
   446	      size_t tmplen = IDN2_LABEL_MAX_LENGTH;
   447	
   448	      rc = label (src, labellen, tmp, &tmplen, flags);
   449	      if (rc != IDN2_OK)
   450	        return rc;
   451	
   452	      if (lookupnamelen + tmplen
   453	          > IDN2_DOMAIN_MAX_LENGTH - (tmplen == 0 && *end == '\0' ? 1 : 2))
   454	        return IDN2_TOO_BIG_DOMAIN;
   455	
   456	      memcpy (_lookupname + lookupnamelen, tmp, tmplen);
   457	      lookupnamelen += tmplen;
   458	
   459	      if (*end == '.')
   460	        {
   461	          if (lookupnamelen + 1 > IDN2_DOMAIN_MAX_LENGTH)
   462	            return IDN2_TOO_BIG_DOMAIN;
   463	
   464	          _lookupname[lookupnamelen] = '.';
   465	          lookupnamelen++;
   466	        }
   467	      _lookupname[lookupnamelen] = '\0';
   468	
   469	      src = end;
   470	    }
   471	  while (*src++);
   472	
   473	  if (lookupname)
   474	    {
   475	      uint8_t *tmp = (uint8_t *) malloc (lookupnamelen + 1);
   476	
   477	      if (tmp == NULL)
   478	        return IDN2_MALLOC;
   479	
   480	      memcpy (tmp, _lookupname, lookupnamelen + 1);
   481	      *lookupname = tmp;
   482	    }
   483	
   484	  return IDN2_OK;
   485	}
